mapper.select:
SELECT ir.result_id, /* * 面试安排实时回退：结果行是「从面试安排生成名单」建的， * 若当时还没排面试则 ir.schedule_id 为空，之后再分配也不会回填—— * 界面会一直显示「无面试」，连带面试分与结论都取不到（它们经 schedule 联表）。 * 这里按简历+周期反查生效安排补上，排完面试立刻就能看到，不必重新生成名单。 */ COALESCE(ir.schedule_id, live.schedule_id) AS schedule_id, ir.user_id, ir.decision, ir.assigned_dept_id, ir.decision_by, ir.decision_at, ir.created_at, ir.updated_at, ir.notified_at, ir.resume_id, -- 优先用结果自身的 cycle_id：没有面试安排的结果查不到 isc.cycle_id（V34） COALESCE(ir.cycle_id, isc.cycle_id) AS cycle_id, u.name as user_name, d.dept_name as department_name, -- 录取决策的三个依据并到一行，免得在「评价汇总」「简历管理」之间来回切： -- 简历分（未署名 = 没打过分 → NULL，不能把默认 0 当成打过 0 分）、 -- 面试评价加权总分与结论、志愿部门 CASE WHEN rs.scored_by IS NULL AND rs.scored_at IS NULL THEN NULL ELSE rs.resume_score END AS resume_score, live.interview_time AS interview_time, ev.total_score AS eval_total_score, ev.recommendation AS eval_recommendation, d1.dept_name AS first_dept_name, d2.dept_name AS second_dept_name FROM interview_result ir LEFT JOIN interview_schedule isc ON ir.schedule_id = isc.schedule_id LEFT JOIN user u ON ir.user_id = u.user_id LEFT JOIN department d ON ir.assigned_dept_id = d.dept_id LEFT JOIN resume rs ON rs.resume_id = COALESCE(ir.resume_id, isc.resume_id) -- 该简历在本周期的生效面试安排（status=1）；一份简历一届只排一次（uk_resume_cycle） LEFT JOIN interview_schedule live ON live.resume_id = COALESCE(ir.resume_id, isc.resume_id) AND live.cycle_id = COALESCE(ir.cycle_id, isc.cycle_id) AND live.status = 1 -- 评价也走回退后的安排 id，否则后排的面试评价永远关联不上 LEFT JOIN interview_evaluation ev ON ev.schedule_id = COALESCE(ir.schedule_id, live.schedule_id) LEFT JOIN interview_preference ip ON ip.resume_id = COALESCE(ir.resume_id, isc.resume_id) LEFT JOIN department d1 ON ip.first_dept_id = d1.dept_id LEFT JOIN department d2 ON ip.second_dept_id = d2.dept_id
AND COALESCE(ir.cycle_id, isc.cycle_id) = #{cycleId}
AND u.name LIKE CONCAT('%', #{name}, '%')
AND ir.decision = #{decision}
AND d.dept_name LIKE CONCAT('%', #{department}, '%')
ORDER BY ir.created_at DESC

SELECT ir.result_id
FROM interview_result ir
LEFT JOIN interview_schedule isc ON ir.schedule_id = isc.schedule_id
WHERE COALESCE(ir.cycle_id, isc.cycle_id) = #{cycleId}
AND ir.result_id IN
#{id}
